package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var a, b, c int
	fmt.Fscan(in, &a, &b, &c)

	sides := []int{a, b, c}
	sort.Ints(sides)
	x, y, z := sides[0], sides[1], sides[2]

	if x+y > z {
		fmt.Println(0)
		return
	}

	// Need x + y > z, so minimal increment is (z - (x + y) + 1)
	ans := z - (x + y) + 1
	fmt.Println(ans)
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var a, b, c int
	fmt.Fscan(in, &a, &b, &c)

	sides := []int{a, b, c}
	sort.Ints(sides)

	// For a triangle of positive area:
	// s0 + s1 > s2
	if sides[0]+sides[1] > sides[2] {
		fmt.Println(0)
		return
	}

	// Need to increase some sticks so that s0 + s1 > s2
	// Minimum increments = (s2 - (s0 + s1) + 1)
	needed := sides[2] - (sides[0] + sides[1]) + 1
	fmt.Println(needed)
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var a, b, c int
	fmt.Fscan(in, &a, &b, &c)

	// Sort a, b, c so that a <= b <= c
	if a > b {
		a, b = b, a
	}
	if b > c {
		b, c = c, b
	}
	if a > b {
		a, b = b, a
	}

	// For a triangle of positive area: a + b > c
	if a+b > c {
		fmt.Println(0)
		return
	}

	// Need to increase a and/or b so that a + b >= c + 1
	needed := c + 1 - (a + b)
	fmt.Println(needed)
}

